from src.models.user import User


USERS = [
    User(id=1, email="ada@example.com", name="Ada", item_ids=[1, 2]),
    User(id=2, email="grace@example.com", name="Grace", item_ids=[3]),
]


def list_users(active_only: bool = True) -> list[dict]:
    return [
        {"id": user.id, "email": user.email, "name": user.name}
        for user in USERS
        if user.active or not active_only
    ]


def get_user(user_id: int) -> User | None:
    for user in USERS:
        if user.id == user_id:
            return user
    return None

from src.models.item import Item


ITEMS = [
    Item(id=1, owner_id=1, name="Notebook"),
    Item(id=2, owner_id=1, name="Pen"),
    Item(id=3, owner_id=2, name="Backpack"),
]


def list_items(include_archived: bool = False) -> list[dict]:
    return [
        item.as_dict()
        for item in ITEMS
        if include_archived or not item.archived
    ]


def get_item(item_id: int) -> dict | None:
    for item in ITEMS:
        if item.id == item_id:
            return item.as_dict()
    return None

from dataclasses import dataclass, field


@dataclass
class User:
    id: int
    email: str
    name: str
    active: bool = True
    item_ids: list[int] = field(default_factory=list)

    def can_login(self) -> bool:
        return self.active and "@" in self.email

    def owns_item(self, item_id: int) -> bool:
        return item_id in self.item_ids

from dataclasses import dataclass


@dataclass
class Item:
    id: int
    owner_id: int
    name: str
    archived: bool = False

    def as_dict(self) -> dict:
        return {
            "id": self.id,
            "owner_id": self.owner_id,
            "name": self.name,
            "archived": self.archived,
        }

